llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Acitretin, a retinoid with a conjugated tetraene carboxylic acid pharmacophore, has an absolute oral bioavailability of about 60% (range 36–95%), showing that retinoids can achieve systemic exposure well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Isotretinoin (13-cis-retinoic acid), structurally close to the retinoid scaffold, has a systemic bioavailability of about 40% at therapeutic doses, supporting F ≥ 20% for retinoid-class molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "All-trans retinoic acid oral bioavailability is estimated at approximately 50% in humans, further supporting that retinoid-type molecules generally achieve oral bioavailability above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "One record reports low absolute bioavailability for 13-cis-retinoic acid with gut degradation, but this is qualitative and contradicted by quantitative retinoid bioavailability data; the query amide may also differ in stability, so this record does not outweigh the quantitative retinoid evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a retinoid amide. Quantitative retinoid analogues (acitretin ~60%, isotretinoin 40%, ATRA ~50%) consistently indicate oral bioavailability above 20%. The only qualitative low record for 13-cis-retinoic acid is less transferable and outweighed by the quantitative retinoid data, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide is provided.",
    "The effect of replacing the carboxylic acid with a p-hydroxyanilide amide on solubility and first-pass metabolism is inferred rather than directly evidenced.",
    "Food effects and formulation dependence for fenretinide are not specified in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

